function createCustomSpeedHud() {
    if (speedHudEl) {
        try { speedHudEl.remove(); } catch (e) { }
        speedHudEl = null;
    }
    speedHudEl = document.createElement("div");
    speedHudEl.id = "galante-speed-hud";
    speedHudEl.style.pointerEvents = "none";
    document.body.appendChild(speedHudEl);
}

function updateCustomSpeed() {
    if (speedMode !== "custom" && speedMode !== "clean" && speedMode !== "minimal") return;
    if (!speedHudEl) return;

    if (!isInVehicle()) {
        speedHudEl.style.display = "none";
        engineRunning = false;
        liveSpeed = 0;
        return;
    }

    speedHudEl.style.display = "block";
    const data = getSpeedFromGame();
    if (speedMode === "minimal") {
        speedHudEl.innerHTML = buildMinimalSpeedHTML(data);
    } else {
        speedHudEl.innerHTML = buildCustomSpeedHTML(data);
    }
}

function enableCustomSpeed(transparent) {
    if (speedUpdateTimer) {
        clearInterval(speedUpdateTimer);
        speedUpdateTimer = null;
    }
    if (speedHudEl) {
        try { speedHudEl.remove(); } catch (e) { }
        speedHudEl = null;
    }
    clearAllSpeedStyles();

    engineRunning = false;
    speedMode = transparent ? "clean" : "custom";
    installGameHooks();
    applyCustomSpeedCSS(!!transparent);
    createCustomSpeedHud();
    updateCustomSpeed();
    speedUpdateTimer = setInterval(updateCustomSpeed, 50);
}

function enableMinimalSpeed() {
    if (speedUpdateTimer) {
        clearInterval(speedUpdateTimer);
        speedUpdateTimer = null;
    }
    if (speedHudEl) {
        try { speedHudEl.remove(); } catch (e) { }
        speedHudEl = null;
    }
    clearAllSpeedStyles();

    engineRunning = false;
    speedMode = "minimal";
    installGameHooks();
    applyMinimalSpeedCSS();
    createCustomSpeedHud();
    updateCustomSpeed();
    speedUpdateTimer = setInterval(updateCustomSpeed, 50);
}

function enableDefaultSpeed() {
    speedMode = "default";
    engineRunning = false;

    if (speedUpdateTimer) {
        clearInterval(speedUpdateTimer);
        speedUpdateTimer = null;
    }
    if (speedHudEl) {
        try { speedHudEl.remove(); } catch (e) { }
        speedHudEl = null;
    }
    clearAllSpeedStyles();

    const restore = document.createElement("style");
    restore.id = "galante-speed-restore";
    restore.textContent = `
        body #app .hud-radmir-speedometer,
        .hud-radmir-speedometer {
            opacity: 1 !important;
            visibility: visible !important;
            pointer-events: auto !important;
        }
    `;
    document.head.appendChild(restore);

    try {
        document.querySelectorAll(".hud-radmir-speedometer").forEach(function (el) {
            el.style.setProperty("opacity", "1", "important");
            el.style.setProperty("visibility", "visible", "important");
            el.style.setProperty("pointer-events", "auto", "important");
            el.style.removeProperty("display");
        });
    } catch (e) { }
}

function openSpeedMenu() {
    window.addDialogInQueue(
        '[0,2,"Спидометр","Выберите спидометр:","Выбрать","Закрыть",0,0]',
        "Дефолт спидометр<n>Черный спидометр<n>Прозрачный спидометр<n>Минималистичный спидометр",
        0
    );
    const orig = window.sendClientEvent;
    window.sendClientEvent = function () {
        const args = Array.prototype.slice.call(arguments);
        if (args.indexOf("OnDialogResponse") !== -1) {
            const raw = (args[5] || "").toString().toLowerCase();
            if (raw.indexOf("дефолт") !== -1 || raw === "0") {
                enableDefaultSpeed();
            } else if (raw.indexOf("минимал") !== -1 || raw === "3") {
                enableMinimalSpeed();
            } else if (raw.indexOf("прозрачн") !== -1 || raw === "2") {
                enableCustomSpeed(true);
            } else if (raw.indexOf("черн") !== -1 || raw.indexOf("чёрн") !== -1 || raw === "1") {
                enableCustomSpeed(false);
            }
            window.sendClientEvent = orig;
        }
        return orig.apply(this, args);
    };
}

